using System;using System.Net;using System.Net.Http;using System.Text.RegularExpressions;using System.Threading;using System.Threading.Tasks;using Microsoft.Extensions.Logging;namespace CriterionArt.Provider;internal static class CriterionLivewireClient{    public static async Task<(string? Snapshot, bool ShouldClearCookies)> GetSearchSnapshotAsync(        HttpClient client, string query, CancellationToken ct, ILogger logger)    {        var url = $"https://www.criterion.com/search?q={Uri.EscapeDataString(query)}";        var solved = await FlareSolverrClient.SolveAsync(client, url, ct);        if (solved is null)        {            logger.LogWarning("CriterionArt: FlareSolverr returned null for search URL");            return (null, false);        }        var html = solved.Html;        logger.LogInformation(            "CriterionArt: search-page htmlLen={Len}, hasSnapshot={HasSnap}",            html.Length, html.Contains("wire:snapshot"));        bool looksChallenged = html.Contains("challenges.cloudflare.com")                                || html.Contains("Cf-Mitigated")                                || html.Contains("jschl-answer");        var snapshotMatch = Regex.Match(html, "wire:snapshot=\"(.*?)\"\\s", RegexOptions.Singleline);        if (!snapshotMatch.Success)        {            logger.LogWarning("CriterionArt: no snapshot found on search page, challenged={Challenged}", looksChallenged);            return (null, looksChallenged);        }        return (WebUtility.HtmlDecode(snapshotMatch.Groups[1].Value), false);    }}